const song = {
  title: "Blue",
  get label() {
    return this.title.toUpperCase();
  },
};

const title = Object.getOwnPropertyDescriptor(song, "title");
const label = Object.getOwnPropertyDescriptor(song, "label");

console.log(title.value, title.writable);
console.log("value" in label, typeof label.get);
console.log(label.enumerable);
console.log(Object.getOwnPropertyDescriptor(song, "artist"));
